INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > Abfall- & Recyclinggesetze
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Einrichtung von IT-Arbeitsplätzen Abfall- und Recyclinggesetze beachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Vorgaben wie das Kreislaufwirtschaftsgesetz sind bindend"}, {"text": "Nein", "correct": false, "because": "Pflicht zur Einhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können alte IT-Geräte ohne Rücksicht auf Recyclingvorschriften entsorgt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Elektroaltgeräte müssen gemäß Vorschriften entsorgt werden"}, {"text": "Ja", "correct": false, "because": "Entsorgung ist reguliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Trennung von Abfall bei der Einrichtung von IT-Arbeitsplätzen gesetzlich vorgeschrieben?', 2, '[{"text": "Ja", "correct": true, "because": "Abfalltrennung ist Teil der Recyclinggesetze"}, {"text": "Nein", "correct": false, "because": "Gesetzliche Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verpackungsmaterialien von IT-Geräten ohne Dokumentation entsorgt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation ist für Rücknahme und Recycling oft erforderlich"}, {"text": "Ja", "correct": false, "because": "Nachweis kann verlangt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Unternehmen bei der Einrichtung von IT-Arbeitsplätzen immer für die fachgerechte Entsorgung verantwortlich?', 2, '[{"text": "Ja", "correct": true, "because": "Unternehmen tragen die Verantwortung gemäß Gesetz"}, {"text": "Nein", "correct": false, "because": "Pflicht besteht"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt primär die Entsorgung von IT-Abfällen in Deutschland?', 3, '[{"text": "Kreislaufwirtschaftsgesetz", "correct": true, "because": "Regelt Abfallwirtschaft und Recycling"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "Für Sicherheit, nicht Abfall"}, {"text": "Datenschutzgesetz", "correct": false, "because": "Für Daten, nicht Entsorgung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist bei der Entsorgung von alten IT-Geräten vorgeschrieben?', 2, '[{"text": "Rückgabe an Sammelstellen", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Verbrennung", "correct": false, "because": "Nicht erlaubt"}, {"text": "Lagerung im Büro", "correct": false, "because": "Keine Lösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Abfalltyp fällt unter spezielle Recyclingvorschriften bei IT-Arbeitsplätzen?', 2, '[{"text": "Elektronikschrott", "correct": true, "because": "Enthält wertvolle und schädliche Stoffe"}, {"text": "Papierabfälle", "correct": false, "because": "Allgemeiner Abfall"}, {"text": "Lebensmittelreste", "correct": false, "because": "Nicht IT-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung haben Unternehmen gemäß dem ElektroG?', 3, '[{"text": "Rücknahme von Altgeräten", "correct": true, "because": "Gesetzliche Pflicht zur Entsorgung"}, {"text": "Verkauf von Altgeräten", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Ignorieren von Vorschriften", "correct": false, "because": "Gesetzeswidrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der Einhaltung von Recyclinggesetzen?', 2, '[{"text": "Ressourcenschonung", "correct": true, "because": "Fördert Wiederverwendung"}, {"text": "Geringere Kosten", "correct": false, "because": "Entsorgung kann kosten"}, {"text": "Schnellere Installation", "correct": false, "because": "Unabhängig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Entsorgung von IT-Abfällen gemäß Gesetz erforderlich?', 4, '[{"text": "Trennung von Materialien", "correct": true, "because": "Fördert Recycling"}, {"text": "Rückgabe an Sammelstellen", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Dokumentation der Entsorgung", "correct": true, "because": "Nachweispflicht"}, {"text": "Verbrennung im Büro", "correct": false, "because": "Nicht erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Abfällen fallen bei der Einrichtung von IT-Arbeitsplätzen an?', 3, '[{"text": "Elektronikschrott", "correct": true, "because": "Alte Geräte"}, {"text": "Verpackungsmaterial", "correct": true, "because": "Von neuen Geräten"}, {"text": "Batterien", "correct": true, "because": "In Geräten enthalten"}, {"text": "Lebensmittelabfälle", "correct": false, "because": "Nicht IT-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einhaltung von Abfall- und Recyclinggesetzen?', 3, '[{"text": "Umweltschutz", "correct": true, "because": "Reduziert Schadstoffe"}, {"text": "Ressourcenschonung", "correct": true, "because": "Wiederverwendung von Materialien"}, {"text": "Gesetzeskonformität", "correct": true, "because": "Vermeidet Strafen"}, {"text": "Geringere Arbeitszeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Anforderungen gelten für IT-Abfälle?', 4, '[{"text": "Fachgerechte Entsorgung", "correct": true, "because": "Schutz vor Schadstoffen"}, {"text": "Rücknahmepflicht", "correct": true, "because": "Hersteller verantwortlich"}, {"text": "Trennungspflicht", "correct": true, "because": "Fördert Recycling"}, {"text": "Freie Entsorgung", "correct": false, "because": "Nicht erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Recyclinggesetze bei IT-Arbeitsplätzen?', 3, '[{"text": "Wiederverwertung", "correct": true, "because": "Materialien nutzen"}, {"text": "Spezielle Sammelstellen", "correct": true, "because": "Organisierte Entsorgung"}, {"text": "Dokumentation", "correct": true, "because": "Nachverfolgbarkeit"}, {"text": "Verbrennung", "correct": false, "because": "Nicht umweltfreundlich"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Kreislaufwirtschaftsgesetz regelt IT-Abfallentsorgung. b) Alte IT-Geräte dürfen im Hausmüll entsorgt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetz ja, Hausmüll nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Elektronikschrott muss getrennt entsorgt werden. b) Recyclinggesetze betreffen nur Papierabfälle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "E-Schrott ja, Gesetze umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unternehmen sind für die Entsorgung von IT-Abfällen verantwortlich. b) Verpackungsmaterial kann ohne Rücksicht entsorgt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verantwortung ja, Verpackung reguliert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Rückgabe an Sammelstellen ist gesetzlich vorgeschrieben. b) Recyclinggesetze fördern Ressourcenschonung.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Rückgabe und Schonung korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Batterien aus IT-Geräten müssen separat entsorgt werden. b) Dokumentation der Entsorgung ist freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Batterien ja, Dokumentation Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

